  const AW_OLD = "3b7e1c94-5d2a-4f08-9c6e-81a4d07f2b53";
  const AW_NEW = "9e4f2a61-0c7b-4d93-b8a5-27f6c1e0d348";
  const AW_DEVICE = (cope) => ["", `Id                     : ${cope ? AW_NEW : AW_OLD}`,
    `DeviceName             : ${cope ? "rcampos_AndroidEnterprise_11/11/2026_10:02 AM" : "rcampos_AndroidForWork_10/11/2026_8:47 AM"}`,
    "UserPrincipalName      : rcampos@contoso.com", "Model                  : SM-A556B (Galaxy A55)", "SerialNumber           : R5CX21LQ8KP",
    "OperatingSystem        : Android", "OsVersion              : 15",
    `DeviceType             : ${cope ? "androidEnterprise" : "androidForWork"}`,
    `ManagedDeviceOwnerType : ${cope ? "company" : "personal"}`,
    `DeviceEnrollmentType   : ${cope ? "androidEnterpriseCorporateWorkProfile" : "userEnrollment"}`,
    `EnrollmentProfileName  : ${cope ? "Contoso COPE - Stores" : ""}`,
    "ManagementState        : managed", "ComplianceState        : compliant",
    `EnrolledDateTime       : ${cope ? "11/11/2026 10:02:41" : "10/11/2026 08:47:12"}`, ""];
