    actions: [
      { id: "status", label: { en: "Codec status", es: "Estado del códec" }, cmd: "poly status " + PY_CODEC },
      { id: "reboot", label: { en: "Restart the room", es: "Reiniciar la sala" }, cmd: "poly reboot " + PY_CODEC },
    ],
